def build():
 content=json.loads(PATH.read_text());out={}
 # Exact shared steps receive the authoritative English paragraphs from their
 # separate finite-proof sidecar, keeping one maintained source for common text.
 common={}
 side=ROOT/'corpus/public/translations/shared-finite.en.json'
 if side.exists():
  for p in json.loads(side.read_text()).get('shared_proofs',{}).values():
   for step in p.get('proof_steps',[]):common[step['id']]=step
 for r in content['results']:
  title,overview=HEADS[r['id']];en={'title':title,'overview':overview}
  if r.get('completion_scope'):en['completion_scope']=r['completion_scope'] if not any('\u3400'<=x<='\u9fff' for x in r['completion_scope']) else overview
  if r.get('assumptions'):
   if r['id'] in ['f11-and-variance','f11-or-variance']:en['assumptions']=ASSUMPTIONS['noise']
   elif r['id'] in ['iclr2024-generalizable-andor','iclr2024-generalizable-and','iclr2024-generalizable-or']:en['assumptions']=ASSUMPTIONS['label']
   elif r['id']=='f11-external-sparsity':en['assumptions']=['The original empirical well-trained-DNN wording and three conditions cited from Ren et al. (2024), rather than newly introduced premises.']
   elif r['id']=='f11-proposition1':en['assumptions']=['The original well-trained wording is retained without introducing a project premise.']
   elif r['id']=='f11-rowmax-penalty':en['assumptions']=['A finite family of at least one model, with a fixed row S.']
   elif r['id']=='f11-boolean-decomposition':en['assumptions']=['Boolean input coordinates are 0 or 1. A zero input baseline is used for support calculations. The algebraic function identity holds for all five Boolean variables.']
   else:en['assumptions']=ASSUMPTIONS['finite']
  if r.get('definitions') and isinstance(r['definitions'][0],dict):en['definitions']=[{'id':d['id'],'body_md':LABEL if 'label' in d['id'] else COORD} for d in r['definitions']]
  steps=[]
  for step in r.get('proof_steps',[]):
   if step['id'] in STEPS:
    heading,body=STEPS[step['id']];row={'id':step['id'],'title':heading,'body_md':body,'justification':JUST.get(step['id'],'')}
   elif step['id'] in common:
    row={k:v for k,v in common[step['id']].items() if k in ['id','title','body_md','justification']}
   else:raise ValueError('Missing shared English step '+step['id']+'; run after shared-finite.en.json is delivered')
   steps.append(row)
  en['proof_steps']=steps
  # These source tabs contain project translations of mathematical statements,
  # not invented verbatim quotations from the author.
  if r['id'] in SOURCE_EXTRA:en['source_material_summary_md']=SOURCE_EXTRA[r['id']]

  en['notation_map']=[{**{k:v for k,v in m.items() if k not in ['meaning','note']},**({'meaning':'Fixed-input, fixed-baseline masked-output game; the empty output is unrestricted.'} if m.get('meaning') else {})} for m in r.get('notation_map',[])]
  out[r['id']]=en
 OUT.parent.mkdir(parents=True,exist_ok=True);OUT.write_text(json.dumps({'schema_version':1,'paper_id':content['paper_id'],'translation_type':'project_translation','results':out,'issues':ISSUES},ensure_ascii=False,indent=2)+'\n')
 return len(out)
if __name__=='__main__':print(build())
